// Login helpers. The passphrase is generated by the app (about 124 bits of randomness),
// so a fast salted SHA-256 is safe here. Slow hashing would not fit the free plan's CPU limit.

const DAY = 24 * 60 * 60 * 1000;
export const MAX_FAILURES = 5; // tries per username and IP ...
export const LOCK_MS = 15 * 60 * 1000; // ... in 15 minutes
export const IP_TRIES = 10; // login tries per IP ...
export const IP_WINDOW_MS = 60 * 1000; // ... in one minute
export const SESSION_MS = 90 * DAY;
export const RENEW_BELOW_MS = 60 * DAY; // renew the cookie when less than 60 days remain
export const MAX_SESSION_MS = 180 * DAY; // hard limit: sign in again after 180 days, however active

// On https the cookie is "__Host-fz_s": Secure, whole site, no Domain, so no other site or subdomain can set it.
// Local dev on http://127.0.0.1 or http://localhost cannot hold a Secure cookie in every browser,
// so there (and only there) it is plain "fz_s".
export const SESSION_COOKIE = "__Host-fz_s";
export const DEV_SESSION_COOKIE = "fz_s";

export function isLocalDev(url: string): boolean {
  const u = new URL(url);
  return u.protocol === "http:" && ["127.0.0.1", "localhost", "[::1]"].includes(u.hostname);
}

export function sessionCookieName(url: string): string {
  return isLocalDev(url) ? DEV_SESSION_COOKIE : SESSION_COOKIE;
}

const ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789"; // no 0/o, 1/l/i

function randomChars(n: number): string {
  const out: string[] = [];
  const limit = 256 - (256 % ALPHABET.length); // reject to avoid modulo bias
  while (out.length < n) {
    const buf = crypto.getRandomValues(new Uint8Array(n * 2));
    for (const b of buf) {
      if (b < limit && out.length < n) out.push(ALPHABET[b % ALPHABET.length]);
    }
  }
  return out.join("");
}

/** Like "k7mqx-2hd9w-pzr4c-u8vbn-e3tfa": 25 characters in 5 groups. */
export function generatePassphrase(): string {
  const raw = randomChars(25);
  return raw.match(/.{5}/g)!.join("-");
}

/** Typed passphrases are compared without case, spaces or dashes, so typing it by hand is forgiving. */
export function normalizePassphrase(p: string): string {
  return p.toLowerCase().replace(/[\s-]/g, "");
}

export function normalizeUsername(u: string): string {
  return u.trim().toLowerCase();
}

function toHex(buf: ArrayBuffer): string {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export async function sha256Hex(text: string): Promise<string> {
  return toHex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text)));
}

export function newSalt(): string {
  return toHex(crypto.getRandomValues(new Uint8Array(16)).buffer as ArrayBuffer);
}

export async function hashPassphrase(passphrase: string, salt: string): Promise<string> {
  return sha256Hex(`finanzas-v1:${salt}:${normalizePassphrase(passphrase)}`);
}

/** Session token for the cookie (base64url, 32 random bytes). Only its hash is stored. */
export function newSessionToken(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** Constant-time comparison of two equal-length hex strings. */
export function sameHex(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

/**
 * Login counters (M1). Every try is counted in one atomic step BEFORE the passphrase is checked,
 * so tries sent at the same moment cannot slip past the limit.
 * A window starts at the first try and lasts windowMs; inside it at most `max` tries are allowed.
 */
export function windowState(tries: number, windowStart: number, now: number, max: number, windowMs: number) {
  const retryAfterS = Math.max(1, Math.ceil((windowStart + windowMs - now) / 1000));
  return { allowed: tries <= max, last: tries >= max, triesLeft: Math.max(0, max - tries), retryAfterS };
}

/**
 * The part of an IP address that one person controls: the whole IPv4 address,
 * or the first 64 bits of an IPv6 address (one home or phone gets a whole /64).
 */
export function ipBucket(ip: string | undefined | null): string {
  const raw = (ip ?? "").trim().toLowerCase();
  if (!raw) return "unknown";
  const mapped = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/.exec(raw);
  if (mapped) return mapped[1];
  if (!raw.includes(":")) return raw;
  const [head, tail] = raw.split("::");
  const h = head ? head.split(":") : [];
  const t = tail !== undefined ? (tail ? tail.split(":") : []) : [];
  const groups = tail !== undefined ? [...h, ...Array(Math.max(0, 8 - h.length - t.length)).fill("0"), ...t] : h;
  return groups.slice(0, 4).map((g) => (parseInt(g, 16) || 0).toString(16)).join(":") + "::/64";
}

/** Counter keys. Hashed so the table never holds an IP address or a typed username. */
export async function ipKey(ip: string | undefined | null): Promise<string> {
  return "ip:" + (await sha256Hex("finanzas-ip:" + ipBucket(ip)));
}
export async function nameKey(username: string, ip: string | undefined | null): Promise<string> {
  return "name:" + (await sha256Hex("finanzas-name:" + normalizeUsername(username) + "\n" + ipBucket(ip)));
}

// ---------- own password (the fallback when Face ID does not work) ----------
// The phone runs PBKDF2-SHA256 with PW_ITER rounds on the salt the server gives, so the slow part never
// costs the Worker's CPU (the free plan allows about 10 ms). The phone sends the 32-byte result as hex;
// the server keeps a salted SHA-256 of it, like the passphrase. The password itself never leaves the phone.
export const PW_ITER = 600_000;
export const PW_MIN = 12; // characters, checked on the phone
export const PW_KEY_RE = /^[0-9a-f]{64}$/;

export async function hashPasswordKey(key: string, salt: string): Promise<string> {
  return sha256Hex(`finanzas-pw-v1:${salt}:${key}`);
}

/** A made-up salt that is the same every time for one username, so a salt answer says nothing about who exists. */
export async function fakeSalt(secretHex: string, username: string): Promise<string> {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secretHex), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const mac = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode("pw-salt:" + normalizeUsername(username)));
  return toHex(mac).slice(0, 32);
}

/** The backup code is the app-made passphrase: 25 characters of the passphrase alphabet once normalized. */
export function looksLikePassphrase(p: string): boolean {
  return /^[abcdefghjkmnpqrstuvwxyz23456789]{25}$/.test(normalizePassphrase(p));
}

/** When a session made at createdAt and expiring at expiresAt should now expire (renewal, capped at 180 days). */
export function renewedExpiry(createdAt: number, expiresAt: number, now: number): number | null {
  if (expiresAt - now >= RENEW_BELOW_MS) return null;
  const next = Math.min(now + SESSION_MS, createdAt + MAX_SESSION_MS);
  return next > expiresAt ? next : null;
}
